s = ''

def Palindrome_substr (s):
    inv_s  = s[::-1]
    org_str = [i for i in s]

    def indices(lst, item):
        return [i for i, x in enumerate(lst) if x == item]

    orginal = []

    if s == inv_s:
        orginal.append(s)

    else:        
        tem = [i for i in org_str if org_str.count(i) >1]
        tem = list(set(tem))

        tem
        distance = 0

        for k in tem:
            org_index = indices(org_str, k)

            for i in range(len(org_index)):            
                try:
                    for j in range(i,len(org_index)):
                        o = s[org_index[i]: org_index[j+1]+1]
                        if o == o[::-1] and len(o) > distance:
                            orginal.append(o)
                            distance = len(o)

                except:
                    pass

    return max(orginal, key= len) if orginal else s[0]

Palindrome_substr(s)
